/*
 * ProductShop generated-page runtime (copied to output/script.js by the compiler).
 * The HTML is generated by Java; this script only selects the requested
 * product page and wires browser interactions to Flask for real CRUD.
 * Static HTML files CANNOT persist to app.py by themselves.
 */
(function () {
  "use strict";

  function selectPageInstance() {
    var instances = Array.from(document.querySelectorAll(".page-instance"));
    if (!instances.length) return;

    var params = new URLSearchParams(window.location.search);
    var key = params.toString();
    var selected = null;
    instances.forEach(function (instance) {
      if (instance.getAttribute("data-page-key") === key) selected = instance;
    });
    // Preserve existing behavior when opening a parameterized HTML file without
    // a query. Explicit unknown product_ids must never silently select product 1.
    if (!selected && !key) selected = instances[0];

    instances.forEach(function (instance) {
      instance.hidden = instance !== selected;
    });
    if (selected) {
      document.title = selected.getAttribute("data-page-title") || document.title;
    } else {
      var notice = document.createElement("p");
      notice.className = "page-instance-missing";
      notice.appendChild(document.createTextNode("No generated page matches '" + key + "'. "));
      var back = document.createElement("a");
      back.href = "index.html";
      back.textContent = "Back to products";
      notice.appendChild(back);
      document.body.insertBefore(notice, document.body.firstChild);
    }
  }

  function configureForms() {
    document.querySelectorAll('form[method="POST"], form[method="post"]').forEach(function (form) {
      // Browsing file:///.../output/index.html is supported for navigation.
      // Real add/edit/delete requires a running Flask server, not file://.
      // Absolute-path actions like /edit/2 would otherwise resolve to
      // file:///edit/2, producing the browser's "File not found" error.
      // Also bridge a static preview on http.server :8000 to Flask :5000.
      var staticPreview = window.location.protocol === "file:" ||
        (window.location.hostname === "127.0.0.1" || window.location.hostname === "localhost") &&
        window.location.port === "8000";
      if (staticPreview) {
        var action = form.getAttribute("action") || "";
        if (action.startsWith("/") && !action.startsWith("//")) {
          var origin = window.PRODUCTSHOP_SERVER_ORIGIN || "http://127.0.0.1:5000";
          form.setAttribute("action", origin.replace(/\/$/, "") + action);
        }
      }
      // Keep original Flask routes and generated HTML routes independent.
      // Original Jinja pages never include this marker and persist source data
      // only. Generated pages send the marker so Flask also regenerates HTML.
      if (/(?:^|\/)output\//.test(window.location.pathname)) {
        var marker = form.querySelector('input[name="_generated_site"]');
        if (!marker) {
          marker = document.createElement("input");
          marker.type = "hidden";
          marker.name = "_generated_site";
          marker.value = "1";
          form.appendChild(marker);
        }
      }
      var question = form.getAttribute("data-confirm");
      if (question) {
        form.addEventListener("submit", function (event) {
          if (!window.confirm(question)) event.preventDefault();
        });
      }
    });
  }

  function installCategoryFilters() {
    // Works on both the original Flask page and the generated index.html.
    // Filtering is presentation-only: it never changes products or app.py.
    var bar = document.querySelector(".category-bar");
    if (!bar) return;
    var filters = Array.from(bar.querySelectorAll("[data-category-filter]"));
    var cards = Array.from(document.querySelectorAll(".product-grid .product-card"));
    var feedback = document.getElementById("category-filter-feedback");
    var empty = document.getElementById("category-filter-empty");
    if (!filters.length) return;

    function applyFilter(category) {
      var visible = 0;
      cards.forEach(function (card) {
        var match = category === "all" || card.getAttribute("data-category") === category;
        card.hidden = !match;
        if (match) visible += 1;
      });
      filters.forEach(function (filter) {
        var active = filter.getAttribute("data-category-filter") === category;
        filter.classList.toggle("chip--active", active);
        filter.setAttribute("aria-pressed", active ? "true" : "false");
      });
      if (empty) empty.hidden = visible !== 0 || cards.length === 0;
      if (feedback) {
        feedback.hidden = category === "all" || cards.length === 0;
        feedback.textContent = "Showing " + visible + " of " + cards.length +
          " product(s)" + (category === "all" ? "" : " in " + category);
      }
    }

    filters.forEach(function (filter) {
      filter.addEventListener("click", function () {
        applyFilter(filter.getAttribute("data-category-filter"));
      });
    });
    applyFilter("all");
  }

  function installImagePreview() {
    var instances = document.querySelectorAll(".page-instance");
    var scopes = instances.length ? Array.from(instances) : [document.body];
    scopes.forEach(function (scope) {
      var input = scope.querySelector('input[name="image"]');
      var group = scope.querySelector("#preview-group");
      var preview = scope.querySelector("#image-preview");
      if (!input || !group || !preview) return;
      var fallback = "https://placehold.co/400x300?text=Invalid+URL";
      function update() {
        var value = input.value.trim();
        if (value) {
          preview.src = value;
          group.hidden = false;
        } else {
          group.hidden = true;
          preview.removeAttribute("src");
        }
      }
      input.addEventListener("input", update);
      preview.addEventListener("error", function () {
        if (preview.src !== fallback) preview.src = fallback;
      });
      update();
    });
  }

  function init() {
    selectPageInstance();
    configureForms();
    installImagePreview();
    installCategoryFilters();
  }
  // Also works if a future version of the compiler moves the script to <head>.
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();
